export class Store {
  constructor() { this.entries = new Map(); }
  save(key, value) { this.entries.set(key, value); }
  get(key) { return this.entries.get(key); }
}

export async function importFile(read, store = new Store(), history = new HistoryLog()) {
  const text = await read();
  const value = JSON.parse(text);
  store.save('current', value);
  history.record({ size: text.length });
  return value;
}

export class HistoryLog {
  constructor() { this.entries = []; }
  record(entry) { this.entries.push(entry); }
  latest() { return this.entries.at(-1); }
}

import { Store } from '../store.js';
export function exportCurrent(store = new Store()) {
  return JSON.stringify(store.get('current'));
}
